{"code":"def transform(grid):
    a=[r[:] for r in grid]
    H,W=len(a),len(a[0])
    lines=[]
    # full horizontal/vertical monochrome lines
    for i in range(H):
        if a[i][0]!=0 and all(x==a[i][0] for x in a[i]): lines.append(('h',i,a[i][0]))
    for j in range(W):
        if a[0][j]!=0 and all(a[i][j]==a[0][j] for i in range(H)): lines.append(('v',j,a[0][j]))
    linecells={(i,j) for typ,k,c in lines for i in (range(H) if typ=='v' else [k]) for j in (range(W) if typ=='h' else [k])}
    # markers are nonzero cells not belonging to lines
    marks=[]
    for i in range(H):
        for j in range(W):
            if a[i][j]!=0 and (i,j) not in linecells: marks.append((i,j,a[i][j]))
    for i,j,c in marks: a[i][j]=0
    for i,j,c in marks:
        choices=[x for x in lines if x[2]==c]
        if not choices: continue
        typ,k,_=min(choices,key=lambda x: abs((i if x[0]=='h' else j)-x[1]))
        if typ=='h':
            a[k-1 if i<k else k+1][j]=c
        else:
            a[i][k-1 if j<k else k+1]=c
    return a"}

